import fluent.syntax.ast as FTL
from fluent.migratetb.helpers import VARIABLE_REFERENCE, transforms_from
from fluent.migratetb.transforms import REPLACE, PLURALS, REPLACE_IN_TEXT


def migrate(ctx):
    """Bug 1935334 - Migrate chatNotifications from PluralForm.sys.mjs, part {index}."""

    source = "mail/chrome/messenger/chat.properties"
    target = reference = "mail/messenger/chat.ftl"

    ctx.add_transforms(
        target,
        reference,
        [
            FTL.Message(
                id=FTL.Identifier("bundled-message-preview"),
                value=PLURALS(
                    source,
                    "bundledMessagePreview",
                    VARIABLE_REFERENCE("count"),
                    foreach=lambda n: REPLACE_IN_TEXT(
                        n,
                        dict(
                            {
                                "#1": VARIABLE_REFERENCE("count"),
                                "%1$S": VARIABLE_REFERENCE("preview"),
                            }
                        ),
                    ),
                ),
            )
        ],
    )
